from pathlib import Path
import pandas as pd

# Get the project folder.
ROOT = Path(__file__).resolve().parents[1]

# Load the results generated by the pipeline.
OUTPUT = pd.read_csv(ROOT / "outputs" / "results.csv")


def get_row(route, week):
    # Find the result for the given route and week.
    result = OUTPUT[
        (OUTPUT["route"] == route)
        & (OUTPUT["week_of"] == week)
    ]

    # Make sure there is exactly one matching record.
    assert len(result) == 1, f"Expected one row for {route}, {week}"

    return result.iloc[0]


def test_delhi_jaipur_sample():
    row = get_row("Delhi-Jaipur", "2024-11-11")

    # Check the expected cost and comparison values.
    assert row["cost_per_tonne_km"] == 4.17
    assert row["vs_own_history"] == "+35.5% vs this route's past average"
    assert row["vs_similar_routes"] == "+21.0% vs similar-length routes this week"

    # The unexplained increase should be flagged without a note ID.
    assert row["flagged"] == "Yes"
    assert pd.isna(row["matched_note_id"])


def test_ahmedabad_mumbai_sample():
    row = get_row("Ahmedabad-Mumbai", "2025-01-20")

    # Check the expected cost and comparison values.
    assert row["cost_per_tonne_km"] == 3.29
    assert row["vs_own_history"] == "+29.5% vs this route's past average"
    assert row["vs_similar_routes"] == "+22.5% vs similar-length routes this week"

    # Check that the increase is justified by note N002.
    assert row["flagged"] == "No (justified)"
    assert row["matched_note_id"] == "N002"


def test_mumbai_pune_sample():
    row = get_row("Mumbai-Pune", "2025-09-15")

    # Check the expected cost and comparison values.
    assert row["cost_per_tonne_km"] == 3.98
    assert row["vs_own_history"] == "+9.2% vs this route's past average"
    assert row["vs_similar_routes"] == "+23.6% vs similar-length routes this week"

    # Note N006 should not justify this cost increase.
    assert row["flagged"] == "Yes"
    assert pd.isna(row["matched_note_id"])